@js:(function(){
  function BLN_H(){var v='';
    try{v=String(source.get('blnHost')||'')}catch(e){}
    if(!v||v=='null'||v=='undefined'){try{var st=String(source.getVariable()||'');if(st){var o=JSON.parse(st);v=String(o.blnHost||'')}}catch(e2){}}
    if(!v||v=='null'||v=='undefined'){try{v=String(cache.get('blnHost')||'')}catch(e3){}}
    if(!v||v=='null'||v=='undefined'){try{v=String(java.get('blnHost')||'')}catch(e4){}}
    var m=String(v).match(/^(https?:\/\/[^\/]+)/);
    return m?m[1]:String(source.bookSourceUrl).replace(/\/+$/,'');
  }
  var _H = BLN_H();
  var items = [];
  function makeWenkuPath(overrides) {
    var cfg = ['lastupdate', '0', '0', '0', '0', '0', '0', '0', '{{page}}', '0'];
    var keys = ['order', 'tagid', 'isfull', 'anime', 'rgroupid', 'sortid', 'typeid', 'words', 'page', 'update'];
    for (var n = 0; n < keys.length; n++) {
      if (overrides[keys[n]] != null) { cfg[n] = overrides[keys[n]]; }
    }
    return _H + '/wenku/' + cfg.join('_') + '.html';
  }
  var pg = org.jsoup.Jsoup.parse(java.ajax(_H + '/wenku/'));
  var groups = pg.select('ul#filters li.sort-li');
  var idx = 0;
  while (idx < groups.size()) {
    var grp = groups.get(idx);
    var head = grp.select('h3.sort-li-title').first();
    var label = head != null ? head.text() : '';
    items.push({title: '>> ' + label + ' <<', url: '', style: {layout_flexGrow: 1, layout_flexBasisPercent: 1}});
    var opts = grp.select('a.btn-tag.jsTag');
    var j = 0;
    while (j < opts.size()) {
      var opt = opts.get(j);
      var ov = {};
      ov[opt.attr('data-filter-type')] = opt.attr('data-filter-value');
      items.push({title: opt.text(), url: makeWenkuPath(ov), style: {layout_flexGrow: 1}});
      j++;
    }
    idx++;
  }
  return JSON.stringify(items);
})()

