var BLN_LINES=['https://www.bilinovel.net','https://bilinovel.net','https://w.linovelib.com'];
var BLN_TAG=['主域·直出内容','301入口→主域','301入口→主域'];

function BLN_gv(k){var v='';
  try{v=String(source.get(k)||'')}catch(e){}
  if(!v||v=='null'){try{var st=String(source.getVariable()||'');if(st){var o=JSON.parse(st);v=String(o[k]||'')}}catch(e2){}}
  if(!v||v=='null'){try{v=String(java.get(k)||'')}catch(e3){}}
  if(!v||v=='null'){try{v=String(cache.get(k)||'')}catch(e4){}}
  if(v=='undefined')v='';return v;}
function BLN_norm(h){var m=String(h||'').match(/^(https?:\/\/[^\/]+)/);return m?m[1]:'';}
function BLN_short(h){return String(h||'').replace(/^https?:\/\//,'');}
function BLN_H(){var h=BLN_norm(BLN_gv('blnHost'));return h?h:'https://www.bilinovel.net';}
function BLN_w(h){h=BLN_norm(h)||'https://www.bilinovel.net';
  try{source.put('blnHost',h)}catch(e0){}
  try{var o={},v=String(source.getVariable()||'');try{o=v?(JSON.parse(v)||{}):{}}catch(e1){o={}}o.blnHost=h;source.setVariable(JSON.stringify(o))}catch(e2){}
  try{java.put('blnHost',h)}catch(e3){}
  try{cache.put('blnHost',h)}catch(e4){}return h;}
function BLN_toast(t){try{java.toast(t)}catch(e){try{java.longToast(t)}catch(e2){}}}
function BLN_curText(){return '当前线路 '+BLN_short(BLN_H());}
function BLN_lineBtn(i){var L=BLN_LINES[i];var sp=BLN_gv('blnsp'+i);var tg=BLN_TAG[i]||'';
  return (BLN_H()==L?'✅ ':'⬜ ')+BLN_short(L)+(tg?'\n'+tg:'')+(sp?'\n'+sp:'');}
function BLN_switch(i){var L=BLN_LINES[i];if(!L)return;BLN_w(L);
  try{java.log('哔哩轻小说切换线路: '+L)}catch(e){}
  // 刷新发现页两级缓存（内存+磁盘），失败则提示手动长按刷新
  var ok=false;try{java.reUiView(true);ok=true}catch(e2){}
  BLN_toast('已切到入口 '+BLN_short(L)+'（'+(BLN_TAG[i]||'')+ '），搜索/发现下次请求即生效；' + (ok?'发现页已自动刷新':'发现页若不变请长按源→刷新'));
  if(String(BLN_TAG[i]||'').indexOf('301')>=0){BLN_toast('提示：该入口会被站点301汇入主域，内容URL仍显示主域属正常现象')}}
function BLN_testAll(){var out='';
  for(var i=0;i<BLN_LINES.length;i++){var t0=new Date().getTime(),det='?',cap='?';
    try{var d=String(java.ajax(BLN_LINES[i]+'/novel/2353.html'));det=d.length>3000?'详情OK':'详情短'+d.length}catch(e){det='详情FAIL'}
    try{var r0=String(java.ajax(BLN_LINES[i]+'/search.html?searchkey='+encodeURIComponent('机战'+i)+',{"followRedirects":false}'));
        var hop=(r0.length<600&&r0.indexOf('book-ol')<0)?'↪301汇入':'直出';
        var r=String(java.ajax(BLN_LINES[i]+'/search.html?searchkey='+encodeURIComponent('机战'+i)));
        cap=hop+(r.indexOf('search_challenge')>=0?'·需码':(r.indexOf('间隔时间')>=0?'·限流':(r.indexOf('book-ol')>=0?'·出结果':'·异常')));
      }catch(e2){cap='搜索FAIL'}
    try{source.put('blnsp'+i,(new Date().getTime()-t0)+'ms')}catch(e3){}
    out+=BLN_short(BLN_LINES[i])+'  '+(new Date().getTime()-t0)+'ms  '+det+'  '+cap+'\n';
    if(i<BLN_LINES.length-1){try{Packages.java.lang.Thread.sleep(5400)}catch(e4){}}}
  BLN_toast('线路体检\n'+out);}
function BLN_cap(kw){kw=String(kw||'机战');var H=BLN_H(),p='';
  try{p=String(java.ajax(H+'/search.html?searchkey='+encodeURIComponent(kw)))}catch(e){BLN_toast('请求失败 '+e);return}
  if(p.indexOf('search_challenge')<0){
    if(p.indexOf('间隔时间')>=0){BLN_toast('站点限流：两次搜索需间隔5秒，稍等再点一次')}
    else{BLN_toast('该线路当前无需验证码 ✓ '+BLN_short(H))}return}
  var cid=(p.match(/name="search_challenge"[^>]*value="([0-9a-f]{32})"/)||[,''])[1];
  var st=(p.match(/name="searchtype"[^>]*value="([^"]*)"/)||[,'all'])[1];
  var img=H+'/checkcode.php?scope=search&module=article&id='+cid+'&r='+new Date().getTime(),pr='';
  try{pr=String(java.ajax(img))}catch(e2){}
  if(pr.length<200){BLN_toast('取不到验证码图片(会话不通)，请用②浏览器过码');return}
  var code='';try{code=String(java.getVerificationCode(img))}
  catch(e3){BLN_toast('弹窗不可用/已取消，请用②浏览器过码');return}
  if(!code||code=='null'){BLN_toast('未输入验证码');return}
  var r2='';try{r2=String(java.ajax(H+'/search.html,'+JSON.stringify({method:'POST',
      body:'searchkey='+encodeURIComponent(kw)+'&searchtype='+st+'&search_challenge='+cid+'&search_code='+code})))}
  catch(e4){BLN_toast('提交失败 '+e4);return}
  if(r2.indexOf('search_challenge')>=0){BLN_toast('验证码不正确 ✗ 再点一次重填')}
  else if(r2.indexOf('间隔时间')>=0){BLN_toast('验证已提交，但撞上5秒限流：稍等再搜一次即可')}
  else{BLN_toast('验证通过 ✓ 30分钟内免验证')}}
function BLN_web(){try{java.startBrowser(BLN_H()+'/search.html','哔哩轻小说·搜索验证')}
  catch(e){BLN_toast('本面板不支持调浏览器，请用①直接填码')}}
function BLN_reset(){try{java.clearCookie()}catch(e){}
  try{cookie.removeCookie(source.key)}catch(e2){}
  BLN_toast('已清 Cookie：下次搜索会重新要求验证')}
function login(){BLN_toast('无需账号登录：用面板可切换线路/测速/过验证码')}

