@js:(function(){
  function BLN_H(){var v='';
    try{v=String(source.get('blnHost')||'')}catch(e){}
    if(!v||v=='null'||v=='undefined'){try{var st=String(source.getVariable()||'');if(st){var o=JSON.parse(st);v=String(o.blnHost||'')}}catch(e2){}}
    if(!v||v=='null'||v=='undefined'){try{v=String(cache.get('blnHost')||'')}catch(e3){}}
    if(!v||v=='null'||v=='undefined'){try{v=String(java.get('blnHost')||'')}catch(e4){}}
    var m=String(v).match(/^(https?:\/\/[^\/]+)/);
    return m?m[1]:String(source.bookSourceUrl).replace(/\/+$/,'');
  }
  var B = BLN_H();
  var k = encodeURIComponent(key);
  try { java.put('blnKey', String(key)); } catch (e0) {}
  // 站点级限流：两次搜索间隔不得少于 5 秒 → 自动等待，避免抓到「错误_哔哩轻小说」空页当成无结果
  var last = 0;
  try { last = parseInt(String(source.get('blnT')||'0'),10)||0; } catch(e1) {}
  if(!last){ try { last = parseInt(String(cache.get('blnT')||'0'),10)||0; } catch(e2) {} }
  if (last > 0) {
    var wait = 5300-(new Date().getTime()-last);
    if (wait > 0) { try { Packages.java.lang.Thread.sleep(wait>7000?7000:wait); } catch(e3) {} }
  }
  var now = String(new Date().getTime());
  try { source.put('blnT',now); } catch(e4) {}
  try { cache.put('blnT',now); } catch(e5) {}
  var url = page == 1 ? B + '/search.html?searchkey=' + k : B + '/search/' + k + '_' + page + '.html';
  try { java.put('blnUrl', url); } catch (e6) {}
  // 翻页终止：读站点自身总页数，不写死上限
  if (page > 1) {
    var tot = 0;
    try { tot = parseInt(String(java.get('blnP_' + key) || '0'), 10) || 0; } catch (e7) {}
    if (!tot) { try { tot = parseInt(String(source.get('blnP_' + key) || '0'), 10) || 0; } catch (e8) {} }
    if (tot > 0 && page > tot) { return null; }
  }
  return url;
})()
